mapper.sql:
WHERE t.deleted = FALSE

    AND (c.course_name ILIKE #{q.keywordLike} ESCAPE '\'
      OR l.lecturer_name ILIKE #{q.keywordLike} ESCAPE '\'
      OR t.participants ILIKE #{q.keywordLike} ESCAPE '\')


    AND t.course_id = #{q.courseId}


    AND t.lecturer_id = #{q.lecturerId}


    AND t.round_no = #{q.roundNo}


    AND t.course_conclusion = #{q.courseConclusion}


    AND t.lecturer_conclusion = #{q.lecturerConclusion}


    AND t.inconsistent = #{q.inconsistent}


    AND t.record_state = #{q.recordState}


    AND t.trial_date >= #{q.dateFrom}


    AND t.trial_date <= #{q.dateTo}
